  <!-- DURASI -->
  <section id="durasi">
    <div class="section-header">
      <div class="section-label">⏱ Transparansi Proses</div>
      <h2 class="section-title">Estimasi Durasi Proses</h2>
      <p class="section-desc">Kami berkomitmen pada transparansi. Berikut estimasi waktu penyelesaian setiap jenis
