        <div class="durasi-unit">hari kerja</div>
        <div class="durasi-badge badge-blue">⚡ Prioritas</div>
      </div>
      <div class="durasi-card">
        <div class="durasi-icon">📄</div>
        <div class="durasi-name">Surat Tugas</div>
        <div class="durasi-time">1</div>
        <div class="durasi-unit">hari kerja</div>
        <div class="durasi-badge badge-blue">⚡ Prioritas</div>
      </div>
      <div class="durasi-card">
        <div class="durasi-icon">📨</div>
        <div class="durasi-name">Surat Keluar</div>
        <div class="durasi-time">1</div>
        <div class="durasi-unit">hari kerja</div>
        <div class="durasi-badge badge-blue">⚡ Prioritas</div>
      </div>
      <div class="durasi-card">
        <div class="durasi-icon">💰</div>
        <div class="durasi-name">Pencairan Selindo</div>
        <div class="durasi-time">3–5</div>
        <div class="durasi-unit">hari kerja</div>
        <div class="durasi-badge badge-yellow">🔄 Proses Bertahap</div>
      </div>
    </div>
