        <div class="flow-node">
          <div class="flow-circle">🔍</div>
          <div class="flow-label">Verifikasi<div class="flow-sub">Admin memeriksa</div>
          </div>
        </div>
      </div>
      <div class="flow-arrow">→</div>
      <div class="flow-step">
        <div class="flow-node">
          <div class="flow-circle">📋</div>
          <div class="flow-label">Penomoran<div class="flow-sub">Pemberian Nomor surat</div>
          </div>
        </div>
      </div>
      <div class="flow-arrow">→</div>
      <div class="flow-step">
        <div class="flow-node">
          <div class="flow-circle">✍️</div>
          <div class="flow-label">Approval<div class="flow-sub">TTD Pimpinan</div>
          </div>
        </div>
      </div>
      <div class="flow-arrow">→</div>
      <div class="flow-step">
        <div class="flow-node">
          <div class="flow-circle">📤</div>
          <div class="flow-label">Distribusi<div class="flow-sub">Dokumen diterbitkan</div>
          </div>
        </div>
      </div>
      <div class="flow-arrow">→</div>
      <div class="flow-step">
        <div class="flow-node">
          <div class="flow-circle">🗄️</div>
          <div class="flow-label">Arsip<div class="flow-sub">Simpan di sistem</div>
          </div>
        </div>
      </div>
    </div>
  </section>

