      </div>
      <div class="modal-body">
        <div class="modal-title" id="modalTitle">Masuk sebagai Staf</div>
        <div class="modal-subtitle" id="modalSubtitle">Akses pengajuan dan status dokumen Anda</div>
        <div class="role-tabs">
          <button class="role-tab" id="tab-staf" onclick="switchRole('staf')"><span>👤</span>Staf</button>
          <button class="role-tab" id="tab-admin" onclick="switchRole('admin')"><span>⚙️</span>Admin</button>
          <button class="role-tab" id="tab-pimpinan" onclick="switchRole('pimpinan')"><span>👔</span>Pimpinan</button>
        </div>
        <form method="POST" id="loginForm">
          @csrf
          <div class="form-group">
            <label class="form-label">Nama</label>
            <input class="form-input" type="text" name="nama" id="inputNama" placeholder="Masukkan Nama">
          </div>
          <div class="form-group">
            <label class="form-label">NIP / Username</label>
            <input class="form-input" type="text" name="nip" id="inputUser" placeholder="Masukkan NIP atau username">
          </div>
          <div class="form-group">
            <label class="form-label">Password</label>
            <div class="password-wrapper">
              <input class="form-input" type="password" name="password" id="inputPass" placeholder="••••••••">
              <i class="fa-solid fa-lock toggle-password" id="iconPass" onclick="togglePassword('inputPass', this)"></i>
            </div>
          </div>
          <button type="button" class="form-submit" onclick="doLogin()">Masuk</button>
