  <script>
    // Inject background image
    document.querySelector('.hero-bg').style.backgroundImage = "url('data:image/jpeg;base64,')";

    (function () {
      const s = localStorage.getItem('sakp-theme') || 'dark';
      document.documentElement.setAttribute('data-theme', s);
      document.getElementById('themeIcon').textContent = s === 'dark' ? '🌙' : '☀️';
    })();
    function toggleTheme() {
      const h = document.documentElement;
      const d = h.getAttribute('data-theme') === 'dark';
      h.setAttribute('data-theme', d ? 'light' : 'dark');
      document.getElementById('themeIcon').textContent = d ? '☀️' : '🌙';
      localStorage.setItem('sakp-theme', d ? 'light' : 'dark');
    }

    const loginUrls = { staf: '/login/staf', admin: '/login/admin', pimpinan: '/login/pimpinan' };
    const roleConfig = { staf: { icon: '👤', title: 'Masuk sebagai Staf', sub: 'Akses pengajuan dan status dokumen Anda' }, admin: { icon: '⚙️', title: 'Masuk sebagai Admin', sub: 'Kelola verifikasi dan penomoran dokumen' }, pimpinan: { icon: '👔', title: 'Masuk sebagai Pimpinan', sub: 'Approval dokumen dan monitoring kinerja' } };
    let currentRole = 'staf';

    function openModal(role) {
      currentRole = role || 'staf'; applyRole(currentRole);
      document.getElementById('modalOverlay').classList.add('open');
      document.body.style.overflow = 'hidden';
      setTimeout(() => document.getElementById('inputNama').focus(), 200);
    }
    function closeModal() { document.getElementById('modalOverlay').classList.remove('open'); document.body.style.overflow = ''; }
    function handleOverlayClick(e) { if (e.target === document.getElementById('modalOverlay')) closeModal(); }
    function applyRole(role) {
      if (!roleConfig[role]) return;

      const m = document.getElementById('loginModal');
      m.className = 'modal role-' + role;

      document.getElementById('modalIcon').textContent = roleConfig[role].icon;
      document.getElementById('modalTitle').textContent = roleConfig[role].title;
      document.getElementById('modalSubtitle').textContent = roleConfig[role].sub;

      ['staf', 'admin', 'pimpinan'].forEach(r => {
        document.getElementById('tab-' + r).className =
          'role-tab' + (r === role ? ' active-' + r : '');
      });
    }
    function switchRole(role) { currentRole = role; applyRole(role); }
    function doLogin() {
      const nama = document.getElementById('inputNama').value.trim();
      const user = document.getElementById('inputUser').value.trim();
      const pass = document.getElementById('inputPass').value.trim();

      if (!nama || !user || !pass) {
        alert('Harap isi semua field yang diperlukan.');
        return;
      }

      const form = document.getElementById('loginForm');
      form.action = loginUrls[currentRole]; // set action sesuai role
      form.submit(); // kirim POST ke Laravel
    }
    document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

    function animateCount(id, target, decimal = false, duration = 1800) {
      const el = document.getElementById(id); let start = 0;
      const step = target / (duration / 16);
      const t = setInterval(() => {
        start = Math.min(start + step, target);
        el.textContent = decimal ? start.toFixed(1) : Math.round(start);
        if (start >= target) { el.textContent = decimal ? target.toFixed(1) : target; clearInterval(t); }
      }, 16);
    }

    const obs = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          ['cnt1', 'cnt2', 'cnt3', 'cnt4'].forEach(id => {
            const el = document.getElementById(id);
            const target = parseFloat(el.dataset.target) || 0;
            const decimal = el.dataset.decimal === 'true';
            animateCount(id, target, decimal);
          });
          obs.disconnect();
        }
      });
    }, { threshold: .3 });
    obs.observe(document.getElementById('statistik'));

    const _origSwitchRole = window.switchRole;

    window.switchRole = function (role) {
      if (typeof _origSwitchRole === 'function') _origSwitchRole(role);

      const sec = document.getElementById('registerSection');
      if (sec) {
        sec.style.display = role === 'staf' ? 'block' : 'none';
      }

      // Update form action
      const form = document.getElementById('loginForm');
      if (form) form.action = `/login/${role}`;
    };

    // Inisialisasi saat modal dibuka
    document.addEventListener('DOMContentLoaded', () => {
      // Pastikan tab staf aktif secara default
      if (typeof switchRole === 'function') switchRole('staf');
    });

    function togglePassword(inputId, iconEl) {
      const input = document.getElementById(inputId);
      const isHidden = input.type === 'password';
      input.type = isHidden ? 'text' : 'password';

      if (isHidden) {
        iconEl.classList.remove('fa-lock');
        iconEl.classList.add('fa-unlock');
      } else {
        iconEl.classList.remove('fa-unlock');
        iconEl.classList.add('fa-lock');
      }
    }
  </script>
</body>

